26	    /**
27	     * Reindirizza a oath per collegamento utente-app
28	     */
29	    public function authorize(Request $request, AuthService $authService)
30	    {
31	        // url di rientro dopo autorizzazione: edit del profilo utente
32	        $authUrl = $authService->authorizationUrl(route("authorize.callback"), $request->user()->id);
33	        
34	        return redirect()->to($authUrl);
35	
36	    }
