39	    /**
40	     * Rientro dopo autorizzazione strava
41	     */
42	    public function authorizeCallback(Request $request, AuthService $authService)
43	    {
44	        $user = $request->user();
45	
46	        // negazione permessi
47	        if($request->error && $request->error == 'access_denied') {
48	            throw new StravaConnectScopeException();
49	        } 
50	        
51	        // validazione
52	        if (!strlen($request->code)) {
53	            abort(400);
54	        }
55	
56	        // controllo id utente prima di uscita
57	        $userId = $user->id;
58	        $exitUserId = $request->get("state");
59	        if ($exitUserId != $userId) {
60	            throw new Exception("Discrepanza id utente nel rientro da strava");
61	        }
62	
63	
64	        // validazione permessi
65	        $avalScopes = $request->scope ? explode(",", $request->scope) : [];
66	        if (!in_array("read", $avalScopes) || !in_array("activity:read", $avalScopes) ) {
67	            throw new StravaConnectScopeException($user);
68	        }
69	    
70	        // scambio il codice per i dati utente
71	        $data = $authService->tokenExchange($request->code);
72	
73	        // salvo utente
74	        $user->registerApp($data);
75	
76	        return redirect(RouteServiceProvider::HOME);
77	
78	
79	    }
