10	
11	/**
12	 * Wrapper around strava apis to process 
13	 * users' registration and authorization
14	 */
15	class AuthService
16	{
17	
18	    /**
19	     * Http client
20	     */
21	    protected Client $connectedAdapter;
22	
23	
24	    /**
25	     * @param Client $clientId
26	     * @param string $clientSecret
27	     */
28	    public function __construct(Client $client) {
29	        $this->connectedAdapter = $client;
30	    }
31	
32	    
33	    /**
34	     * Istanzia ouath
35	     * // TODO passare da fuori ed eliminare accesso a config strava
36	     */
37	    protected function oauth($params = []) {
38	    
39	        $options = array_merge([
40	            'clientId'     => config('strava.client_id'),
41	            'clientSecret' => config('strava.client_secret'),
42	        ], $params);
43	
44	        return new OAuth($options);
45	
46	    }
47	
48	
49	
50	    /**
51	     * Crea url di autorizzazione
52	     * @param string url di redirect dopo autorizzazione
53	     * @param mixed $state parametro ulteriore ritornato nella query di stringa di rientro da strava
54	     */
55	    public function authorizationUrl($redirectUrl, $state = null) {
56	
57	        $oauth = $this->oauth(['redirectUri'  => $redirectUrl]);
58	
59	        $params = [
60	            'response_type'   => 'code',
61	            'approval_prompt' => 'auto',
62	            'scope'=> ['activity:read']
63	        ];
64	        if ($state !== null) {
65	            $params["state"] = $state;
66	        }
67	                    
68	        return $oauth->getAuthorizationUrl($params);
69	
70	    }
71	
72	
73	    /**
74	     * Scambia codice ricevuto in ritorno da autorizzazione per un token d'accesso.
75	     * Il token ritornato è un istanza di League\OAuth2\Client\Token\AccessTokenInterface.
76	     * @see https://oauth2.thephpleague.com/
77	     */
78	    public function tokenExchange($code) : ? AccessTokenInterface {
79	
80	        $oauth = $this->oauth();
81	
82	        $data = $oauth->getAccessToken('authorization_code', [
83	            'code' => $code
84	        ]);
85	
86	        return $data;
87	    
88	    }
89	
90	
91	    /**
92	     * Refresh del token
93	     * @param string $refresh_token token dedicato al refresh ottenuto nella prima autenticazione
94	     */
95	    public function tokenRefresh(string $refresh_token)  : ? AccessTokenInterface {
96	
97	        $data = $this->oauth()->getAccessToken($grant = 'refresh_token', $params = [
98	            "refresh_token" => $refresh_token,
99	        ]);     
100	
101	        return $data;
102	    }
103	
104	
105	
106	    /**
107	     * Check if a token needs refresh.
108	     * If so, refresh it and store it for the user.
109	     */
110	    public function checkAndRefreshTokenForUser(User $user) : string
111	    {   
112	
113	        // se il token non è scaduto, im fermo
114	        // controllo la scadenza con un range
115	        $tokenExpire = Carbon::parse($user->token_expires_at);
116	        $validityTreshold = 30; // voglio almeno 30 secondi di validità
117	
118	        // ho validità inferiore a quella desiderata, è scaduto
119	        if ($tokenExpire < (new Carbon())->addSeconds($validityTreshold)) {
120	            $token = $this->tokenRefresh($user->refresh_token);
121	
122	            $user->access_token = $token->getToken();
123	            $user->refresh_token = $token->getRefreshToken();
124	            $user->token_expires_at_timestamp = $token->getExpires();
125	            $user->token_expires_at = Carbon::parse($token->getExpires());
126	            $user->save();
127	
128	            // return new access token
129	            return $user->access_token;
130	        }
131	
132	        // token is still valid, we can return it
133	        return $user->access_token;
134	    }
135	
136	
137	    
138	}

