8	/**
9	 * Extends vendor RESt to forward exceptions to the outside
10	 */
11	class StravaRest extends REST implements ServiceInterface
12	{
13	    /**
14	     * Get an API request response and handle possible exceptions.
15	     *
16	     * @param string $method
17	     * @param string $path
18	     * @param array $parameters
19	     *
20	     * @return array|mixed|string
21	     * @throws \GuzzleHttp\Exception\GuzzleException
22	     */
23	    protected function getResponse($method, $path, $parameters)
24	    {
25	        try {
26	            $response = $this->adapter->request($method, $path, $parameters);
27	            $result = $this->getResult($response);
28	
29	            if ($this->responseVerbosity === 0 && !is_string($result)) {
30	                return $result["body"];
31	            }
32	
33	            return $result;
34	        } catch (\Exception $e) {
35	            throw $e;
36	        }
37	    }
38	}
