18	
19	/**
20	 * Process a single webhook notification
21	 */
22	class WebhookProcess implements ShouldQueue
23	{
24	    use Dispatchable;
25	    use InteractsWithQueue;
26	    use Queueable;
27	    use SerializesModels;
28	
29	    /**
30	     * @var Webhook the webhook being processed
31	     */
32	    protected $item;
33	
34	
35	    /**
36	     * The number of times the job may be attempted.
37	     *
38	     * @var int
39	     */
40	    public $tries = 20;
41	
42	    /**
43	     * The maximum number of unhandled exceptions to allow before failing.
44	     *
45	     * @var int
46	     */
47	    public $maxExceptions = 3;
48	
49	    /**
50	     * Create a new job instance.
51	     *
52	     * @return void
53	     */
54	    public function __construct(Webhook $item)
55	    {
56	        $this->item = $item;
57	    }
58	
59	    /**
60	     * Execute the job.
61	     *
62	     *
63	     * @return void
64	     */
65	    public function handle(Adapter $adapter, AuthService $authService)
66	    {
67	
68	
69	        /**
70	         * If we are processing a "delete" aspect_type, try to locale the local activity
71	         * and delete it.
72	         */
73	        if($this->item->aspect_type == 'delete') {
74	            $activity = Activity::where('ext_id', $this->item->object_id)->first();
75	            if($activity) {
76	                $activity->delete();
77	            }
78	            $this->item->processed = 'Y';
79	            $this->item->save();
80	            return;
81	        }
82	
83	
84	        /**
85	         * get the owner
86	         */
87	        $user = $this->item->owner;
88	        if(!$user) {
89	            $this->item->status_code = 'user_not_found';
90	            $this->item->processed = 'Y';
91	            $this->item->save();
92	            return;
93	        }
94	
95	
96	        /**
97	         * Refresh token if needed
98	         */
99	        $token = $authService->checkAndRefreshTokenForUser($user);
